#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Generate zero-delay behavioural models for the sky130_fd_sc_hd cells used
by the TVLA netlists, straight from the pinned Liberty file's `function` /
`ff` groups (Yosys read_liberty), so every model matches the .lib that was
used for mapping and area.

usage: gen_cell_models.py LIB OUT.v NETLIST.v [NETLIST.v ...]
"""
import hashlib, os, re, subprocess, sys, tempfile

HEADER = """\
// SPDX-License-Identifier: Apache-2.0
// GENERATED by tools/gen_cell_models.py -- do not edit; `make cells` rebuilds.
// Zero-delay behavioural models derived from {lib}
// (sha256 {sha}), part of the SkyWater SKY130 PDK,
// Copyright 2020 The SkyWater PDK Authors, Licensed under the Apache License,
// Version 2.0 <http://www.apache.org/licenses/LICENSE-2.0>. See sim/VENDOR.md.
// No timing, no power, no glitches: functional models only.
"""


def used_cells(paths):
    used = set()
    for p in paths:
        used |= set(re.findall(r"^\s*(sky130_fd_sc_hd__\w+)\s+\S+\s*\(",
                               open(p).read(), re.M))
    return sorted(used)


def main():
    lib, out, nets = sys.argv[1], sys.argv[2], sys.argv[3:]
    cells = used_cells(nets)
    if not cells:
        sys.exit("no sky130 cells found in netlists")
    yosys = os.environ.get("YOSYS", "yosys")
    with tempfile.TemporaryDirectory() as td:
        tmp = os.path.join(td, "m.v")
        sel = " ".join(cells)
        subprocess.run([yosys, "-q", "-p",
                        f"read_liberty -ignore_miss_func {lib}; "
                        f"select {sel}; "
                        f"write_verilog -noattr -selected {tmp}"],
                       check=True)
        body = open(tmp).read()
    body = re.sub(r"^/\*.*?\*/\n", "", body, flags=re.S | re.M)
    have = set(re.findall(r"^module\s+(\w+)", body, re.M))
    missing = [c for c in cells if c not in have]
    if missing:
        sys.exit(f"Liberty has no function for: {missing}")
    sha = hashlib.sha256(open(lib, "rb").read()).hexdigest()
    with open(out, "w") as f:
        f.write(HEADER.format(lib=os.path.basename(lib), sha=sha))
        f.write("`timescale 1ns/1ps\n")
        f.write(body)
    print(f"{len(cells)} cell models -> {out}")


if __name__ == "__main__":
    main()
